def count_distinct_characters(string: str) -> int:
    # Convert the input string to lowercase to ignore case differences
    string = string.lower()

    # Count unique characters
    unique_chars = set()
    for char in string:
        if char.isalpha():  # Consider only alphabetic characters
            unique_chars.add(char)

    # Return the count
    return len(unique_chars)  # Return the size of the set as the number of distinct characters
def count_distinct_characters(string: str) -> int:
    string = string.lower()
    unique_chars = set()
    for char in string:
        if char.isalpha():
